-- ==============================================================================
-- 墨云项目 · 数据库初始化 DML：AI 智能体模块（模型/供应商/智能体/工具/词典/场景）
-- 覆盖范围：ai_provider、ai_model_config、ai_agent、ai_agent_tool、ai_agent_tool_relation、ai_agent_dictionary_relation、ai_domain_dictionary、ai_scene_config、ai_knowledge_config_template
-- 前置条件：已按顺序执行 zyg_ddl_01_sys_ai.sql、zyg_ddl_02_biz_job.sql
-- 幂等性：全部使用 REPLACE INTO（按主键 / 唯一键覆盖），可反复执行；
--         重复执行会以本脚本为准覆盖同主键行，手工改动过的预置行会被重置。
-- 字符集：文件为 UTF-8 无 BOM，请用 mysql --default-character-set=utf8mb4 导入
-- ==============================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

-- ############################################################################
-- # 一、AI 供应商与模型 ai_provider / ai_model_config
-- ############################################################################

-- ----------------------------------------------------------------------------
-- ai_provider · AI 提供商注册表（5 行）
-- 供应商注册表：openai / dashscope / ollama / deepseek / moonshot
-- ----------------------------------------------------------------------------
REPLACE INTO `ai_provider` (`id`, `code`, `name`, `api_style`, `default_base_url`, `supports_streaming`, `requires_api_key`, `enabled`, `sort_order`, `remark`, `create_time`, `update_time`, `deleted`) VALUES (1,'openai','OpenAI','openai_compatible','https://api.openai.com/v1',1,1,1,1,'OpenAI 官方及兼容端点','2026-09-07 09:15:27',NULL,0),(2,'dashscope','通义千问(百炼)','openai_compatible','https://dashscope.aliyuncs.com/compatible-mode/v1',1,1,1,2,'阿里百炼，运行时走 OpenAI 兼容模式','2026-09-07 09:15:27',NULL,0),(3,'ollama','Ollama','ollama_native','http://localhost:11434',1,0,1,3,'本地 Ollama 服务，无需 API Key','2026-09-07 09:15:27',NULL,0),(4,'deepseek','DeepSeek','openai_compatible','https://api.deepseek.com',1,1,1,4,'示例：OpenAI 兼容，后台一键启用','2026-09-07 09:15:27',NULL,0),(5,'moonshot','Moonshot Kimi','openai_compatible','https://api.moonshot.cn/v1',1,1,1,5,'示例：OpenAI 兼容，后台一键启用','2026-09-07 09:15:27',NULL,0);


