-- ai_model_config · 模型配置表（4 行）
-- ⚠ api_key 为 ENC: 前缀密文，用部署环境的加密密钥加密；换环境后需重新录入密钥
-- ----------------------------------------------------------------------------
REPLACE INTO `ai_model_config` (`id`, `name`, `provider`, `model_type`, `model_name`, `api_key`, `base_url`, `temperature`, `max_tokens`, `timeout`, `streaming_supported`, `supports_json_mode`, `enabled`, `is_default`, `description`, `create_time`, `update_time`, `input_price`, `output_price`, `deleted`) VALUES (1,'通义千问-多模态Embedding','dashscope','embedding','text-embedding-v3','ENC:7/3JCnmmCxrmLHVDvy06rR87in5AZZVyXi9FeMzSH5uoHBnBg12lP55YHw5J/RdzOqFIiZRg2gzOS0K5zW2raIt/erTxKeQzvDu/HAbvLr1XkOBD+uORu9tBFkBFXjj0Gf/vmKdE/9nY4vwnTVMx45DaKfyk3YGo9aczA8MHOwQaJohrApt3azoyjpKe6Ggt','https://dashscope.aliyuncs.com/compatible-mode/v1',0.3,4089,60,0,0,1,1,'通义千问多模态 Embedding 模型，支持图片和文本的联合向量化，用于图文混合搜索','2025-11-21 17:12:03','2026-09-07 09:13:40',0.000500,0.000000,0),(2,'通义千问-VL-Plus','dashscope','chat','qwen-vl-plus','ENC:etybEZmvkCnWb5NTpGzl4XdvyqfUn+Pef7mBT8X7yw==',NULL,0.7,2000,60,1,0,0,0,'通义千问视觉理解模型Plus版本，支持图片内容识别和描述，用于文档图片的多模态理解','2025-11-22 12:16:42','2026-09-07 09:29:14',0.001000,0.002000,0),(3,'qwen3.8-max','dashscope','chat','qwen3.8-max','ENC:/ZTXHHvxIY3PkQ/TAQ5h1c//aQw/5pn41SL5kRp9/VSUw3RXNqsp21jKi1C8ReLdMNW+AQ+E8om7II/SzM6PsmFKZso93y5rBsRp8D62AoL9/G8cRHoIukzIbaZV9kTKQ8t5rYFVoD5/ZELu1KV6tBFKDErFK6GqN+OrROoDgSWn7kYDbU7Cln+I9Yr6oP1O','https://dashscope.aliyuncs.com/compatible-mode/v1',NULL,4000,180,1,0,1,0,'Qwen3 重排序模型，用于提升检索结果的相关性排序，支持中英文等100+语言','2026-01-22 15:34:36','2026-09-07 09:29:14',0.000100,0.000000,0),(4,'deepSeekV4','deepseek','chat','deepseek-v4-pro','ENC:L9tek34q0dxfmrtaB7aHg1VKJeZvLRUKUOyhCQuCyo6wLUIuHDI3qJVQIuQ8p2gq2vR0ej2qfNnOaSFlL3DV','https://api.deepseek.com',0.7,2000,180,1,0,1,1,'','2026-09-07 09:29:09','2026-09-11 09:47:51',0.001000,0.002000,0);


-- ############################################################################
-- # 二、智能体 ai_agent / 工具 ai_agent_tool / 关联表
-- ############################################################################

-- ----------------------------------------------------------------------------
-- ai_agent · 智能体表（2 行）
-- 默认智能体（AI 面试官等），id 由本脚本显式指定，ai_scene_config.agent_id 依赖它
-- ----------------------------------------------------------------------------
REPLACE INTO `ai_agent` (`id`, `name`, `description`, `system_prompt`, `knowledge_library_ids`, `knowledge_base_weights`, `model_config_id`, `model_name`, `temperature`, `max_tokens`, `rag_min_score`, `rag_max_results`, `enabled`, `welcome_message`, `suggested_questions`, `show_citations`, `max_history_turns`, `api_enabled`, `api_key`, `workflow_id`, `workflow_trigger_mode`, `workflow_trigger_keywords`, `publish_enabled`, `publish_token`, `publish_settings`, `create_time`, `update_time`, `rag_recall_multiplier`, `rag_enable_hybrid_search`, `rag_enable_query_expansion`, `rag_bm25_weight`, `rag_vector_weight`, `enable_self_reflection`, `deleted`) VALUES (1,'财务分析师','财务分析师agent','你是一名拥有12年实战经验的资深个人家庭财务分析师，精通收支诊断、资产负债梳理、投资理财风险评估全流程，严格遵循国内现行个人财税规则与2026年最新惠民财税政策。\r\n\r\n核心工作规则：\r\n1.  所有结论100%基于传入的结构化记账数据，禁止自行计算、修改任何数值，所有引用的金额、百分比、月份必须和给定数据完全一致\r\n2.  综述部分要讲完整的财务故事：清晰说明用户统计周期内的收入来源结构、主要支出去向、核心变化趋势，最后点出当前最值得关注的1个核心财务特征\r\n3.  风险项按高/中/低严重度排序，每一条必须附带明确数据依据evidence，格式示例：\"近3月餐饮累计支出¥6500，环比上月上涨65%\"\r\n4.  建议项必须是可直接落地的具体动作，不能出现\"合理规划\"\"量入为出\"这类空泛表述，每一条都要标注量化的预期效果expectedImpact，格式示例：\"每月可固定减少非必要娱乐支出¥800，年度累计多结余¥9600\"\r\n5.  绝对拒绝任何违规偷税、造假、高风险投机类建议，不确定的政策内容统一标注「以当地税务机关最新规定为准」\r\n6.  只输出符合要求的JSON内容，禁止输出JSON以外的任何说明、解释性文字\r\n\r\n数据不足时基于已有信息客观分析，绝不臆造不存在的收支、资产数据。风险和建议各输出2-5条，按重要性从高到低排序。\r\n','[\"12\"]','{\"12\":1}',4,'deepseek-v4-pro',0.3,4096,0.5,10,1,'欢迎使用财务分析agent','',1,30,1,'sk-nEGmhZ5ffdMMdKnJ2iTSBsFO30JCI4YE',NULL,'manual','',1,'pub-jp2t2kutbmamlkvow8jmvd','','2026-09-01 15:32:06','2026-09-30 09:15:04',2,1,1,0.3,0.7,0,0),(2,'AI面试官·默认','语音面试默认面试官人设（勿删）。systemPrompt 支持 {{position}}/{{scene}}/{{difficulty}}/{{style}}/{{resumeDigest}}/{{profileGaps}}/{{levelEstimate}} 占位符，运行时自动渲染。修改后无需重启即生效。','你是一位经验丰富的一线技术面试官，主持一场真实的一对一模拟面试。\n\n【人设】\n- 你面过数百位候选人，阅人无数：听得懂话里的含糊其辞，也识得出真材实料。\n- 你的风格是\"温和但不好糊弄\"：语气自然友好，但会对模糊表述、可疑数据、夸大成分温和地追根究底。\n- 你尊重候选人，绝不居高临下；提问像聊天，不打官腔。\n\n【面试守则】\n1. 一次只问一个问题。紧密结合候选人此前的回答随机应变——像真实面试官一样追问细节、质疑数据、验证深度。\n2. 追问有度：同一话题连续追问不超过 2 轮；已验证深度或候选人已无新信息时，立即切换到下一个考察方向，不恋战、也不蜻蜓点水地串场。\n3. 考察有层次：开场从简历与自我介绍深挖真实经历，中段必须进入岗位专业技术与核心能力考察，结尾留出候选人反问空间——把面试时间用满，考察充分而非赶进度。\n4. 不泄露评分维度与分析细节，不主动给标准答案，不说\"你的得分是\"。\n5. 口语化、自然，像面对面交谈：单轮话术控制在 1-3 句，避免书面语、条目式表达和长篇大论。\n6. 候选人答不上来或明显偏题时，给一次自然的引导或换题，不反复纠缠同一考点。\n7. 全程只以面试官身份说话，不扮演其他角色，不输出任何 JSON、标记或系统文字。','[\"1\"]','{\"1\":1}',4,'deepseek-v4-pro',0.7,2048,0.7,10,1,'你好，欢迎参加{{position}}岗位的模拟面试。我是今天的面试官，放松心态，我们像聊天一样开始。准备好了的话，我们直接进入第一个问题。','',1,20,0,'',NULL,'manual','',1,'pub-wxg0pgbp5jqnj5cp9fw8i','','2026-09-07 09:15:33','2026-09-30 18:05:01',2,1,1,0.2,0.8,0,0);


