REPLACE INTO `ai_agent_tool` (`id`, `name`, `display_name`, `description`, `category`, `tool_type`, `icon`, `config`, `parameters`, `timeout_seconds`, `enabled`, `is_system`, `create_time`, `update_time`, `deleted`) VALUES (1,'current_time','当前时间','获取当前的日期和时间，可指定时区和格式','utility','builtin','fa-clock',NULL,'{\"type\": \"object\", \"required\": [], \"properties\": {\"format\": {\"type\": \"string\", \"default\": \"yyyy-MM-dd HH:mm:ss\", \"description\": \"时间格式，默认yyyy-MM-dd HH:mm:ss\"}, \"timezone\": {\"type\": \"string\", \"default\": \"Asia/Shanghai\", \"description\": \"时区，如Asia/Shanghai，默认北京时间\"}}}',30,1,1,'2025-11-25 15:06:30','2025-11-25 15:06:30',0),(2,'calculator','数学计算','执行数学计算，支持加减乘除、幂运算、开方、三角函数等','utility','builtin','fa-calculator',NULL,'{\"type\": \"object\", \"required\": [\"expression\"], \"properties\": {\"expression\": {\"type\": \"string\", \"description\": \"数学表达式，如(1+2)*3、sqrt(16)、sin(30)\"}}}',30,1,1,'2025-11-25 15:06:30','2025-11-25 15:06:30',0),(3,'weather_query','天气查询','查询指定城市的实时天气和未来天气预报（真实数据，Open-Meteo免费接口），包括温度、湿度、风向、天气状况等，预报最多7天','information','builtin','fa-cloud-sun','{\"data_source\": \"open-meteo\"}','{\"type\": \"object\", \"required\": [\"city\"], \"properties\": {\"city\": {\"type\": \"string\", \"description\": \"城市名称，如北京、上海、广州\"}, \"days\": {\"type\": \"integer\", \"default\": 1, \"description\": \"预报天数1-7，默认1天\"}}}',30,1,1,'2025-11-25 15:06:30','2025-11-25 15:06:30',0),(4,'web_search','网络搜索','搜索互联网获取最新信息（真实数据，必应免费接口），适用于查询新闻、事件、知识等实时内容','information','builtin','fa-search','{\"data_source\": \"bing\"}','{\"type\": \"object\", \"required\": [\"query\"], \"properties\": {\"count\": {\"type\": \"integer\", \"default\": 5, \"description\": \"返回结果数量，默认5条\"}, \"query\": {\"type\": \"string\", \"description\": \"搜索关键词\"}}}',30,1,1,'2025-11-25 15:06:30','2025-11-25 15:06:30',0),(5,'url_reader','网页读取','读取指定URL的网页内容，提取主要文本信息','information','http','fa-globe','{\"timeout\": 10}','{\"type\": \"object\", \"required\": [\"url\"], \"properties\": {\"url\": {\"type\": \"string\", \"description\": \"要读取的网页URL\"}}}',30,1,1,'2025-11-25 15:06:30','2025-11-25 15:06:30',0),(6,'translator','文本翻译','将文本翻译成指定语言，支持中英日韩等多种语言互译','utility','http','fa-language','{\"api_type\": \"aliyun\"}','{\"type\": \"object\", \"required\": [\"text\"], \"properties\": {\"to\": {\"type\": \"string\", \"default\": \"zh\", \"description\": \"目标语言代码，如zh/en/ja\"}, \"from\": {\"type\": \"string\", \"default\": \"auto\", \"description\": \"源语言代码，如zh/en/ja，可设为auto自动检测\"}, \"text\": {\"type\": \"string\", \"description\": \"要翻译的文本\"}}}',30,1,1,'2025-11-25 15:06:30','2025-11-25 15:06:30',0),(7,'send_email','发送邮件','发送邮件，支持纯文本和HTML格式，支持多收件人、抄送、密送','action','builtin','fa-envelope','{}','{\"type\": \"object\", \"required\": [\"to\", \"subject\", \"content\"], \"properties\": {\"cc\": {\"type\": \"string\", \"description\": \"抄送人邮箱，多个用英文逗号分隔，可选\"}, \"to\": {\"type\": \"string\", \"description\": \"收件人邮箱，多个用英文逗号分隔\"}, \"bcc\": {\"type\": \"string\", \"description\": \"密送人邮箱，多个用英文逗号分隔，可选\"}, \"isHtml\": {\"type\": \"boolean\", \"default\": false, \"description\": \"正文是否为HTML格式，默认false\"}, \"content\": {\"type\": \"string\", \"description\": \"邮件正文，纯文本或HTML\"}, \"subject\": {\"type\": \"string\", \"description\": \"邮件主题\"}}}',30,1,1,'2025-11-25 15:06:30','2025-11-25 15:06:30',0),(8,'database_query','数据库查询','查询数据库并返回智能分析结果。使用自然语言提问，系统自动生成SQL执行，返回查询结果、统计分析和图表推荐。支持MySQL数据源。','data','database','fa-database','{\"max_rows\": 100}','{\"type\": \"object\", \"required\": [\"datasource_id\", \"query\"], \"properties\": {\"query\": {\"type\": \"string\", \"description\": \"自然语言查询问题，如：统计工具表中已启用的工具数量\"}, \"need_chart\": {\"type\": \"boolean\", \"default\": true, \"description\": \"是否需要图表推荐，默认true\"}, \"datasource_id\": {\"type\": \"integer\", \"description\": \"数据源ID，须为数据源管理中已配置的数据源\"}, \"need_analysis\": {\"type\": \"boolean\", \"default\": true, \"description\": \"是否需要智能分析，默认true\"}}}',30,1,1,'2025-11-25 15:06:30','2025-11-25 15:06:30',0);


