REPLACE INTO `ai_scene_config` (`id`, `scene_code`, `scene_name`, `description`, `scene_category`, `agent_id`, `model_config_id`, `knowledge_library_ids`, `tool_ids`, `workflow_id`, `config_json`, `handler_bean_name`, `handler_method`, `system_prompt_template`, `user_prompt_template`, `prompt_placeholders`, `output_mode`, `output_schema`, `output_parser`, `max_tokens`, `temperature`, `timeout_seconds`, `retry_count`, `rate_limit_key`, `rate_limit_count`, `rate_limit_time`, `daily_token_limit`, `max_input_tokens`, `max_output_tokens`, `truncate_strategy`, `enable_output_filter`, `enable_intent_routing`, `fallback_model_id`, `fallback_response`, `enable_cache`, `cache_ttl`, `version`, `config_version`, `weight`, `priority`, `is_default`, `enabled`, `open_api`, `create_time`, `update_time`, `deleted`) VALUES (1,'voice_interview','AI 语音面试','AI 语音模拟面试：主干走网关会话流式通道，task 子任务（warmup/answer_analysis/self_intro）拆行配置驱动（2B.5，原 VoiceInterviewHandler 已删；人设走 ai_agent(48)）','chat',2,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,NULL,NULL,'sync',NULL,'',2048,0.7,30,3,'',100,60,NULL,NULL,2000,'head_tail',0,0,NULL,'',0,3600,'v1',1,100,0,1,1,0,'2026-09-07 15:07:33','2026-09-30 09:15:09',0),(2,'sensitive_word','敏感词检测','文本敏感词识别与风险分级（2B.3 配置驱动，原 SensitiveWordHandler 提示词逐字收编；降级兜底数据化 fallback_response）','classification',NULL,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'你是内容安全审核专家。检测文本是否包含敏感内容（涉政/色情/暴恐/辱骂/违法广告等），只输出 JSON：\r\n{\"hasSensitive\": true/false,\r\n \"words\": [\"命中的敏感词或类别\"],\r\n \"riskLevel\": \"high/medium/low\",\r\n \"suggestion\": \"处理建议（正常内容给\'无风险\'）\"}\r\n无敏感内容时 hasSensitive=false、words=[]、riskLevel=\"low\"。禁止输出 JSON 以外内容。\r\n\r\n{{data:待检测文本|text}}','{\"text\": \"待检测文本（数据通道隔离）\"}','sync',NULL,'json',2048,0.7,30,3,NULL,100,60,NULL,NULL,NULL,'head_tail',0,0,NULL,'{\"hasSensitive\": false, \"words\": [], \"riskLevel\": \"low\", \"suggestion\": \"AI服务暂时不可用，已跳过检测\"}',0,3600,'v1',1,100,0,1,1,0,'2026-09-09 11:15:46',NULL,0),(3,'daily_topic','今日主题','每日主题生成（2B.2 配置驱动，原 DailyTopicHandler 提示词逐字收编）','generation',NULL,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'你是内容运营专家。为指定日期生成一个当日主题，只输出 JSON：\r\n{\"title\": \"主题标题（15字内，有吸引力）\",\r\n \"description\": \"主题描述（50字内）\",\r\n \"category\": \"分类（技术/职场/生活/热点）\"}\r\n标题避免与历史主题重复。禁止输出 JSON 以外内容。\r\n\r\n日期：{{date}}\r\n{{data:领域|domain}}\r\n{{data:已生成过的标题（避免重复）|excludeTitles}}','{\"date\": \"生成日期（yyyy-MM-dd）\", \"domain\": \"领域（可选，空值自动丢弃）\", \"excludeTitles\": \"已生成过的标题（可选，空值自动丢弃）\"}','sync',NULL,'json',2048,0.7,30,3,NULL,100,60,NULL,NULL,NULL,'head_tail',0,0,NULL,NULL,0,3600,'v1',1,100,0,1,1,0,'2026-09-09 11:15:47',NULL,0),(4,'finance_analysis','AI 财务分析','2B.4 查数下沉：LedgerAiAnalysisServiceImpl 组装 window/ledgerContext，DefaultSceneExecutor 配置驱动执行；人设走 ai_agent(47)','analysis',1,NULL,NULL,NULL,NULL,'{}','defaultSceneExecutor','execute',NULL,'当前统计分析窗口：{{window}}\r\n\r\n以下是系统规则引擎已经计算完成的精确财务数据，包含全量指标、逐月趋势、分类环比、预算执行、债务明细等所有信息，请你直接引用这些数值完成分析，不要自行修改计算：\r\n{{data:财务数据|ledgerContext}}\r\n','{\"window\": \"统计窗口文案，如：本月（自 2026-09-01 起，含数据 3 个月；另附近6个月趋势数据）\", \"ledgerContext\": \"业务 Service 组装的财务上下文 JSON（画像/核心指标护栏/收入来源/支出结构Top5/负债明细含清偿测算/逐月收支趋势/分类环比/预算执行；数据通道隔离）\"}','sync','{\"risks\": [{\"level\": \"string，仅允许取值 high/medium/low\", \"title\": \"string，风险短标题\", \"detail\": \"string，风险详细说明\", \"evidence\": \"string，支撑该风险的具体数据依据\"}], \"summary\": \"string，完整的财务分析综述，讲清周期内的收支故事与核心特征\", \"healthScore\": \"int 0-100，基于传入指标计算的财务健康分\", \"suggestions\": [{\"icon\": \"string，前端可直接使用的图标标识，如 wallet / save / debt / invest\", \"title\": \"string，建议短标题\", \"detail\": \"string，建议的具体执行动作说明\", \"expectedImpact\": \"string，该建议落地后可实现的量化收益效果\"}]}','',2048,0.7,30,3,'aaa',100,60,NULL,6000,4000,'head_tail',0,0,NULL,'',0,3600,'v1',1,100,0,0,1,0,'2026-09-09 18:11:29','2026-09-30 09:15:09',0),(5,'default_chat','智能体对话','智能体动态对话（/cms/ai/chat/*）：治理配置载体（限流/执行日志），Agent 由请求动态指定，人设走 ai_agent.system_prompt','chat',NULL,NULL,NULL,NULL,NULL,NULL,'dynamicChatBridge','execute',NULL,NULL,NULL,'stream',NULL,'text',2048,0.7,30,3,NULL,60,3600,NULL,NULL,NULL,'head_tail',0,0,NULL,NULL,0,3600,'v1',1,100,0,1,1,0,'2026-09-16 17:01:51',NULL,0),(6,'resume_optimize:advice','简历优化-改进建议','task 拆行：评分明细→改进建议（原 ResumeOptimizeHandler.advice 提示词逐字收编）','generation',NULL,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'你是一名资深 HR 与简历顾问，擅长基于评分明细给出可执行的改进建议。请返回 JSON 格式，字段：summary(整体总结), advices(数组，每项含 dimension/priority(high/medium/low)/content/type(fill/refine/match)/optimized), missingSkills(字符串数组)。content 为该维度的改进思路说明；optimized 为优化后的完整可用文本（可直接替换简历对应模块内容），必须基于用户简历现有信息改写而非凭空编造，量化数据无依据时可使用占位符如 [X%] 供用户填写；dimension 取值限定：基本信息/求职意向/教育经历/工作经历/项目经历/技能列表/自我介绍/岗位匹配度。建议要具体、可执行，优先关注得分率低于60%的维度与岗位匹配度缺失技能。只输出 JSON 本体，禁止使用 markdown 代码块（```）包裹，禁止在 JSON 前后添加任何说明文字。\r\n\r\n{{data:业务数据|context}}','{\"context\": \"业务 Service 组装的评分明细/目标岗位上下文（数据通道隔离）\"}','sync',NULL,'json',2048,0.7,30,3,NULL,100,60,NULL,8000,3000,'head_tail',0,0,NULL,NULL,0,3600,'v1',1,100,0,1,1,0,'2026-09-24 12:00:00','2026-09-28 17:34:28',0),(7,'resume_optimize:job_match','简历优化-岗位匹配','task 拆行：JD×简历→匹配报告（原 ResumeOptimizeHandler.job_match 提示词逐字收编）','generation',NULL,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'你是一名资深技术招聘官，负责评估候选人与岗位的匹配度。请基于目标岗位JD和候选人简历，返回 JSON：matchScore(0-100综合匹配度), grade(excellent/good/medium/poor), matchedKeywords(数组,简历已覆盖的JD核心要求关键词), missingKeywords(数组,简历缺失的JD核心要求关键词), dimensions(对象,含四个维度，每维 score 0-100 与 suggestions 数组: keywordMatch关键词匹配/experienceMatch经验匹配/skillMatch技能匹配/structureMatch结构完整度), summary(2-3句总体评价与改进方向)。评估要客观，基于简历真实内容，缺失项如实指出；关键词控制在20个以内。只输出 JSON 本体，禁止使用 markdown 代码块（```）包裹，禁止在 JSON 前后添加任何说明文字。\r\n\r\n{{data:业务数据|context}}','{\"context\": \"业务 Service 组装的岗位JD+候选人简历上下文（数据通道隔离）\"}','sync',NULL,'json',2048,0.7,30,3,NULL,100,60,NULL,8000,3000,'head_tail',0,0,NULL,NULL,0,3600,'v1',1,100,0,1,1,0,'2026-09-24 12:00:00','2026-09-28 17:34:28',0),(8,'resume_optimize:field_assist','简历优化-字段辅助','task 拆行：字段级 3 版本优化（原 ResumeOptimizeHandler.field_assist 提示词逐字收编）','generation',NULL,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'你是一名资深简历优化专家，对简历中的指定字段给出3个不同风格的优化版本。优化原则：STAR法则（情境-任务-行动-结果）、量化数据（无依据数据用[X%][X万]占位符供用户填写）、突出与目标岗位相关的能力、专业商务表达避免口语化、每版50-150字。三个版本风格差异化：版本1侧重成果量化（推荐），版本2侧重技术深度，版本3侧重业务价值。保持与原文语义一致，禁止编造经历。返回 JSON：{\"suggestions\":[{\"text\":\"优化后完整文本\",\"reason\":\"一句话优化理由\"}]}，恰好3条。只输出 JSON 本体，禁止 markdown 代码块包裹，禁止前后说明文字。\r\n\r\n{{data:业务数据|context}}','{\"context\": \"业务 Service 组装的字段原文+字段类型+目标岗位上下文（数据通道隔离）\"}','sync',NULL,'json',2048,0.7,30,3,NULL,100,60,NULL,8000,3000,'head_tail',0,0,NULL,NULL,0,3600,'v1',1,100,0,1,1,0,'2026-09-24 12:00:00','2026-09-28 17:34:28',0),(9,'resume_optimize:draft_empty','简历优化-空字段草稿','task 拆行：空字段初始草稿（原 ResumeOptimizeHandler.draft_empty 提示词逐字收编）','generation',NULL,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'你是一名简历撰写专家。根据用户已有信息，为空缺的字段生成初始草稿。生成原则：STAR 法则（情境-任务-行动-结果）、量化数据（无依据数据用 [X%][X万] 占位符供用户填写）、突出与目标岗位相关的能力、专业商务表达避免口语化。工作经历 2-3 条，每条描述 50-150 字；项目经历 2-3 条，每条描述 50-150 字；自我介绍 100-200 字，突出技能和经验。保持语义合理，禁止编造具体公司名（用 [公司名] 占位符）。返回 JSON：{works:[{company,position,startDate,endDate,description}],projects:[{name,role,startDate,endDate,description}],selfIntro:\"\"}。仅生成空缺字段，已有字段不输出。只输出 JSON 本体，禁止 markdown 代码块包裹，禁止前后说明文字。\r\n\r\n{{data:业务数据|context}}','{\"context\": \"业务 Service 组装的用户已有信息+目标岗位上下文（数据通道隔离）\"}','sync',NULL,'json',2048,0.7,30,3,NULL,100,60,NULL,8000,3000,'head_tail',0,0,NULL,NULL,0,3600,'v1',1,100,0,1,1,0,'2026-09-24 12:00:00','2026-09-28 17:34:28',0),(10,'resume_optimize:deep_optimize','简历优化-深度优化','task 拆行：整份简历逐项深度优化（原 ResumeOptimizeHandler.deep_optimize 提示词逐字收编）','generation',NULL,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'你是一名资深简历优化专家，基于目标岗位JD对简历进行逐项深度优化。返回 JSON：summary(总体优化说明，50字内), items(优化建议数组，3-6项)。每项含：section(必为以下枚举之一：objective/education/work/project/skills/selfIntro；严禁使用复数如works/projects，严禁使用experience/introduction 等同义词，必须完全匹配枚举值), index(列表条目索引，从0开始；skills 填 0), field(position/description/name), optimized(优化后完整文本，可直接替换，50-200字), reason(优化理由，一句话，30字内)。不要输出 original 