ULL,100,60,NULL,NULL,NULL,'head_tail',0,0,NULL,NULL,0,3600,'v1',1,100,0,1,1,0,'2026-09-24 12:00:00',NULL,0),(19,'question_generate:jd_keywords','智能出题-JD关键词','task 拆行：JD 文本→面试考察关键词（2B.3 配置驱动，原 QuestionGenerateHandler.jd_keywords 提示词逐字收编，输出契约改 JSON 对象包装）','classification',NULL,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'从岗位JD中提取面试考察关键词。规则：\r\n1.只提取技术栈、专业能力、业务领域三类实词；\r\n2.每个关键词2-20个字符，保留英文原文大小写（如 Spring Boot）；\r\n3.最多15个，按重要性降序；\r\n4.禁止编造JD中不存在的内容。\r\n只输出JSON对象 {\"keywords\": [\"Java\", \"MySQL\"]}（数组置于 keywords 字段），禁止markdown代码块。\r\n\r\n{{data:岗位JD|context}}','{\"context\": \"岗位 JD 原文（外部不可信数据，数据通道隔离）\"}','sync',NULL,'json',2048,0.7,30,3,NULL,100,60,NULL,NULL,NULL,'head_tail',0,0,NULL,NULL,0,3600,'v1',1,100,0,1,1,0,'2026-09-24 12:00:00',NULL,0),(20,'article_meta','文章元信息','文章摘要/SEO 标题/SEO 描述/关键词（2B.3 配置驱动，原 ArticleMetaHandler+PortalAiController SCENES 提示词收编，输出契约改 JSON）','analysis',NULL,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'你是内容平台的 SEO 编辑。请根据下面的文章标题和正文，输出文章的摘要与 SEO 信息，只输出 JSON：\r\n{\"summary\": \"摘要，100字以内，概括文章核心内容\",\r\n \"seoTitle\": \"SEO标题，60字以内，包含核心关键词，比原标题更利于搜索\",\r\n \"seoDescription\": \"SEO描述，150字以内，吸引点击的搜索结果描述\",\r\n \"seoKeywords\": \"关键词，3~6个，用英文逗号分隔，不要带序号\"}\r\n禁止输出 JSON 以外内容。\r\n\r\n文章标题：{{title}}\r\n{{data:文章正文|content}}','{\"title\": \"文章标题（可空）\", \"content\": \"正文纯文本（调用方截断 3000 字，数据通道隔离）\"}','sync',NULL,'json',2048,0.7,30,3,NULL,100,60,NULL,NULL,NULL,'head_tail',0,0,NULL,NULL,0,3600,'v1',1,100,0,1,1,0,'2026-09-24 12:00:00',NULL,0),(21,'voice_interview:opening_fallback','AI 语音面试-开场降级','task 拆行：warmup 失败后的简版开场白+首题（v13.46 批次 1 自代码 generateOpening 迁移；V1.1#1「收编不删除」——warmup 失败多为瞬时网络抖动，删兜底=一次抖动一场面试开不了头）','chat',2,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'你是一位专业的技术面试官，即将开始一场 {{context}} 岗位的面试（难度：{{difficulty}}）。请用一两句话自然开场，并直接提出第一个问题。要求：① 开场简洁友好，不做冗长自我介绍；② 第一个问题应贴合岗位与难度，可先请候选人做自我介绍或简述与该岗位最相关的经历；③ 只输出开场白与问题本身，不要输出任何解释、标题或 JSON 结构。','{\"context\": \"岗位名称\", \"difficulty\": \"难度\", \"agentPersona\": \"面试官人设（系统提示词）\", \"resumeDigest\": \"候选人简历摘要\"}','sync',NULL,'text',512,0.7,60,0,NULL,30,60,NULL,NULL,NULL,'head_tail',1,0,NULL,'面试官开场生成失败，请稍后重试',0,NULL,'1',1,1,0,1,1,0,'2026-09-30 13:55:58',NULL,0),(22,'voice_interview:hint','AI 语音面试-思考提示','task 拆行：一句话思考引导（不泄答案）（v13.46 批次 1 自代码 requestHint 迁移；计费口径=免费，两级配额：每题3次/全场15次）','chat',2,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'候选人请求思考提示。请以面试官身份给一句简短的思考引导（提示回答方向或组织思路，不直接给出答案），40字以内，只输出这句话。','{\"answer\": \"候选人已作答内容（可空）\", \"question\": \"当前题目\"}','sync',NULL,'text',128,0.7,30,0,NULL,20,60,NULL,NULL,NULL,'head_tail',1,0,NULL,'别着急，可以从你熟悉的相关项目经历入手，按「背景→做法→结果」的思路组织回答。',0,NULL,'1',1,1,0,1,1,0,'2026-09-30 13:55:58',NULL,0),(23,'voice_interview:report_review','AI 语音面试-整场复盘','task 拆行：整场复盘 + 追问预测（一次调用双产出，V1.2 §3.2 裁决不单开——两触点输入同源，单开=输入token翻倍）（v13.46 批次 1 自代码 enhanceReportByAgent 迁移；v13.47 批次 2 扩 levelEstimate 结构化 + predictedQuestions 上限6 + perQuestion 瘦身；2026-10-12 报告评审升级：考察者视角 verdict/profile/competencies/薄弱点归因卡/结构化行动建议 + 话术铁律，retry 0→3、max_tokens 2560→4600）','chat',2,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'【任务】你是一位资深技术面试官，面试已结束。请基于下方候选人资料与整场对话记录，以**考察者视角**输出结构化复盘报告 JSON——读者是候选人本人，目标是让他清楚知道自己当前水平、差距在哪、下一步怎么补。\n【字段要求】\n1. verdict：结论判词，一句话定性整体水平与岗位差距方向，≤60字（如「具备中级后端的工程功底，系统设计与权衡表达是冲击高级的主要短板」）。\n2. profile：候选人画像段，2-4句：技术背景/项目复杂度，对照岗位要求定位（结合简历摘要与自我介绍轮）。\n3. overallComment：3-5句整场总评，结合岗位要求评价整体表现，指出最突出的特点，引用至少一处作答证据。\n4. levelEstimate：候选人水平定级，**只能是 junior / mid / senior 之一**（依据：回答深度、技术准确度、项目复杂度）。\n5. jobMatch：{rate: 0-100整数匹配度, reason: 1-2句依据（对照岗位要求与实际作答）}。\n6. competencies：五维能力剖面，固定5条 {key, label, score, comment, evidenceIdx}：key/label 依次为 depth=技术深度 / engineering=工程实践 / design=系统设计 / communication=沟通表达 / match=岗位匹配；score 为 0-100 整数；comment 2-3句评价，**必须锚定题号或候选人原话**；evidenceIdx 为证据题号数组；对话未直接覆盖的维度，comment 必须注明「本场未直接考察，以下为间接推断」，score 谨慎给，禁止臆造具体表现。\n7. highlights：2-4条真实亮点 {title: ≤12字, detail: 引用作答原话或题号的具体说明}。\n8. weakPoints：2-4条薄弱点**归因卡** {title: ≤12字, detail: 具体不足, type: knowledge(知识缺口)/expression(表达问题)/depth(深度不足)之一, evidence: 哪几题+原话摘要, impact: 该短板在真实面试/工作中会被如何解读, remedy: 动词开头的具体补法≤60字}。禁止把问题原文当薄弱点。\n9. suggestionViews：3-5条结构化行动建议 {action: 动词开头≤50字（如「手写缓存穿透/击穿/雪崩对策对比表」）, acceptance: 验收口径≤40字（能做到什么算过关）, priority: 1-3（1最高）}，按对求职影响排序。\n10. perQuestion：逐题分数修正 [{questionIdx: 题号, score: 0-100整数}]，**仅回填需修正的题**（逐题点评文本由系统复用逐题分析结果，你不需要重复产出）。\n11. dimensions：{relevance 切题度, professionalism 专业深度, fluency 表达流畅, interactivity 互动质量, confidence 自信度, logic 逻辑结构}，0-100整数。\n12. predictedQuestions：追问预测，**最多6条**（已问+未问合计），每条 {question, briefAnswer: 要点式简答≤80字, analysis: 为什么会被问≤60字, knowledgePoint: 考点标签2-6字, askedThisRound: true或false, askedScore: 本场得分（askedThisRound 为 true 时填，否则 null）}。\n   predictedQuestions 硬约束：① 只能基于简历摘要中的**真实内容**提问，禁止推断未提及的经历；② 禁止编造项目名、公司名或技术栈；③ 是否已问**必须以对话记录为准**；④ **未被问到的问题优先覆盖**「简历写了但本场未深挖的条目」与「岗位要求中简历未体现的差距项」。\n【话术铁律】① 评价必须锚定证据：引用题号或候选人原话，禁止无出处的定性（「基础薄弱」这类空话禁止）；② 用对比句式：岗位要求X→作答显示Y→差距是Z；③ 评表现不评人格：说「回答未涉及X」，不说「候选人能力差」；④ 区分「未考察」与「不足」：没问到的方向不得当弱点写；⑤ 标注【自我介绍轮】的轮次仅用于画像与表达评估，禁止作为技术能力证据引用；⑥ 无候选人实质回答的轮次零引用。\n只输出 JSON 对象，不要输出任何其他文本。\n\n【候选人资料与对话记录】\n目标岗位：{{position}}\n岗位要求：{{jd}}\n候选人简历摘要：\n{{resumeDigest}}\n整场对话记录（含每题初评分，供参考）：\n{{qaList}}','{\"jd\": \"岗位要求\", \"qaList\": \"整场对话记录（含每题初评分）\", \"position\": \"岗位名称\", \"resumeDigest\": \"候选人简历摘要\"}','sync',NULL,'json',4600,0.7,180,3,NULL,10,60,NULL,NULL,4096,'head_tail',1,0,NULL,'报告生成中，请稍后重试',0,NULL,'1',1,3,0,1,1,0,'2026-09-30 13:55:58','2026-10-12 10:07:08',0),(24,'voice_interview:industry_insight','AI 语音面试-发展方向','task 拆行：发展方向建议（懒生成：首次打开 tab 才调用；输入追加本场报告上下文以与 resume_optimize:job_match 划清边界；预留 knowledge_library_ids 走 RAG 作为真动态来源）','chat',2,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,'【任务】你是一位资深的职业发展顾问。请结合候选人的目标岗位、简历技能与本场面试暴露的真实薄弱点，输出个人化的发展方向分析 JSON。\n【字段要求】\n1. trends：技术趋势 3-4 条，每条 {title: ≤12字, detail: ≤60字, maturity: 成熟期/上升期/早期}。\n2. supplyDemand：{existing: [简历已具备的技能标签 3-8 个], missing: [建议补充的技能标签 3-8 个]}。\n3. actions：3 条行动建议，每条 {content: ≤80字可执行建议, relatedWeakPoint: 必须引用本场报告中的真实薄弱点原文}。\n【硬约束】① 严禁标注具体百分比、薪酬数字或时效性季度数据（无实时数据，编造时效数据会让用户误信）；\n② 每条行动建议必须锚定本场真实薄弱点，禁止「建议学习云原生」这类与个人无关的通用废话；\n③ 措辞为方向性判断，不承诺实时行业动态。只输出 JSON 对象，不要输出任何其他文本。\n\n【候选人资料】\n目标岗位：{{position}}\n岗位要求：{{jd}}\n简历技能：{{skills}}\n本场薄弱点：{{weakPoints}}\n水平定级：{{levelEstimate}}\n低分维度：{{lowDimensions}}','{\"jd\": \"岗位要求\", \"skills\": \"简历技能\", \"position\": \"岗位名称\", \"weakPoints\": \"本场薄弱点\", \"levelEstimate\": \"水平定级\", \"lowDimensions\": \"低分维度\"}','sync',NULL,'json',1536,0.7,120,3,NULL,5,600,NULL,NULL,NULL,'head_tail',1,0,NULL,'发展方向分析生成失败，请稍后重试',0,3600,'1',1,1,0,1,1,0,'2026-09-30 13:55:58','2026-10-12 10:07:08',0),(25,'workflow_agent_node','工作流Agent节点','AI工作流 agent 节点的统一收口治理场景：AgentNodeExecutor 优先经本场景走网关（限流/Token熔断/计量/日志），未配置/停用时兜底直连并补计量','chat',NULL,NULL,NULL,NULL,NULL,NULL,'defaultSceneExecutor','execute',NULL,NULL,NULL,'sync',NULL,'text',2048,0.7,30,3,NULL,600,60,NULL,NULL,NULL,'head_tail',0,0,NULL,NULL,0,3600,'v1',1,100,0,1,1,0,'2026-10-09 16:25:34',NULL,0);


